//
// The Canvas2D spectrum line: grid, trace, hold, peak marker, clip state.
//
// WHAT THIS FILE MAY AND MAY NOT DO. It may map numbers to pixels. It may not
// change a number: no smoothing (ADR 0006 D8 puts that in linear power, in the
// Worker), no averaging, no re-scaling of dB, no peak of its own — the marker
// it draws is the Worker's `frame.peak`, computed by `peak.py`'s estimator. A
// renderer that computed anything would be a fourth implementation of a
// convention, and ADR 0021 decision 2's star has exactly three arms.
//
// DROP, NEVER QUEUE, is `render/scheduler.ts`'s — see its header for the
// failure it prevents and for why the rule lives in a module node can test.
// `columnsDrawn` and `columnsDropped` are that scheduler's counters, surfaced
// here because they are two of the numbers ADR 0021 decision 3 requires to be
// reported for the web application's refresh (*measured, never claimed*).
//
// devicePixelRatio. `app.css` stretches the canvas to the panel width; the
// `width`/`height` attributes are the BACKING STORE. If the two disagree the
// browser resamples the drawing, and a resampled 1-pixel-wide spectral peak
// moves — which would make the peak marker disagree with the line it is
// pointing at. `resize()` therefore sets the backing store from the measured
// CSS box times `devicePixelRatio` and scales the context once, so every
// coordinate below is in CSS pixels.
//
// NOTHING IS ENCODED BY COLOUR ALONE (WCAG 2.2 SC 1.4.1, bibliography 03 #23).
// The peak marker carries its frequency and level as TEXT beside the crosshair,
// the hold trace is dashed as well as differently coloured, and the clip state
// is the word CLIP, not a red pixel. Contrast itself is a W3 audit and the
// values in `palette.ts` are `(prov.)` until it happens.
// ----------------------------------------------------------------------------

import type { FrameMessage } from '../worker/protocol';
import { browserRafHost, createFrameScheduler, type FrameScheduler, type RafHost } from './scheduler';
import { FALLBACK_PALETTE, type SpectrumPalette } from './palette';

/** The axes, from the preset's `display` block. */
export interface SpectrumViewOptions {
  readonly freqMinHz: number;
  readonly freqMaxHz: number;
  readonly freqScale: 'log' | 'linear';
  readonly dbFloor: number;
  readonly dbCeiling: number;
}

export interface SpectrumView {
  /** Submit a frame for the next animation callback. Newest wins; see the scheduler. */
  draw(frame: FrameMessage): void;
  setOptions(options: SpectrumViewOptions): void;
  setPalette(palette: SpectrumPalette): void;
  /** Re-measure the CSS box and rebuild the backing store. Call from a ResizeObserver. */
  resize(): void;
  readonly columnsDrawn: number;
  readonly columnsDropped: number;
  /** Animation callbacks per second, rolling. The *measured* refresh of ADR 0021 decision 3. */
  rafHz(): number;
  resetCounters(): void;
  destroy(): void;
}

/** Left gutter for the dB labels, and bottom gutter for the frequency labels, in CSS pixels. */
const PADDING = { left: 46, right: 10, top: 10, bottom: 22 } as const;

/** dB grid spacing. 10 dB is the interval every level readout in this project is quoted in. */
const DB_GRID_STEP = 10;

/** Minor frequency ticks inside a decade: the 2…9 of a log axis. */
const DECADE_MINORS = [2, 3, 4, 5, 6, 7, 8, 9] as const;

function clamp(v: number, lo: number, hi: number): number {
  return v < lo ? lo : v > hi ? hi : v;
}

export function createSpectrumView(
  canvas: HTMLCanvasElement,
  palette: SpectrumPalette = FALLBACK_PALETTE,
  options: SpectrumViewOptions,
  host: RafHost = browserRafHost(canvas.ownerDocument.defaultView ?? window),
): SpectrumView {
  // An IIFE rather than `const c = ...; if (c === null) throw;`: the drawing
  // helpers below are hoisted function declarations, and TypeScript does not
  // carry a narrowing from the enclosing flow into them. Typing the binding
  // itself is what makes `context.save()` legal inside `drawGrid`.
  const context = ((): CanvasRenderingContext2D => {
    const found = canvas.getContext('2d');
    if (found === null) {
      throw new Error('this browser did not give a 2d context for the spectrum canvas');
    }
    return found;
  })();

  let currentPalette = palette;
  let currentOptions = options;
  /** CSS-pixel size of the drawing area, refreshed by `resize()`. */
  let cssWidth = canvas.clientWidth > 0 ? canvas.clientWidth : canvas.width;
  let cssHeight = canvas.clientHeight > 0 ? canvas.clientHeight : canvas.height;
  /**
   * The device-pixel ratio the backing store was actually built with.
   *
   * Owned by `resize()` and read by `paint()`. Deriving it instead — as
   * `canvas.width / cssWidth` — is a trap: those two are only in step AFTER a
   * resize, and before the first one `cssWidth` is the HTML `width` attribute
   * while the backing store is whatever a previous view left. The derived ratio
   * is then wrong, the transform is wrong, and the frame paints at the wrong
   * scale on top of the old one. That is the ghost the light-theme screenshot
   * caught on 2026-08-22: a second `dBFS 0` at the old right edge.
   */
  let backingDpr = 1;

  const plot = (): { x: number; y: number; w: number; h: number } => ({
    x: PADDING.left,
    y: PADDING.top,
    w: Math.max(1, cssWidth - PADDING.left - PADDING.right),
    h: Math.max(1, cssHeight - PADDING.top - PADDING.bottom),
  });

  /** Frequency → x. The log axis is what every preset but `vowel_formant_study` asks for. */
  function xOf(hz: number): number {
    const { x, w } = plot();
    const { freqMinHz, freqMaxHz, freqScale } = currentOptions;
    if (freqScale === 'log') {
      const lo = Math.log10(Math.max(freqMinHz, 1e-6));
      const hi = Math.log10(Math.max(freqMaxHz, freqMinHz + 1e-6));
      return x + (w * (Math.log10(Math.max(hz, 1e-6)) - lo)) / (hi - lo);
    }
    return x + (w * (hz - freqMinHz)) / (freqMaxHz - freqMinHz);
  }

  /** Level → y. `dbCeiling` at the top, `dbFloor` at the bottom, clamped into the plot. */
  function yOf(db: number): number {
    const { y, h } = plot();
    const { dbFloor, dbCeiling } = currentOptions;
    const t = (dbCeiling - db) / (dbCeiling - dbFloor);
    return y + h * clamp(t, 0, 1);
  }

  function drawGrid(): void {
    const { x, y, w, h } = plot();
    context.save();
    context.font = '11px ui-monospace, "DejaVu Sans Mono", monospace';
    context.textBaseline = 'middle';

    // --- dB, every 10 dB ---------------------------------------------------
    const { dbFloor, dbCeiling } = currentOptions;
    context.strokeStyle = currentPalette.grid;
    context.fillStyle = currentPalette.axisText;
    context.lineWidth = 1;
    const first = Math.ceil(dbFloor / DB_GRID_STEP) * DB_GRID_STEP;
    for (let db = first; db <= dbCeiling; db += DB_GRID_STEP) {
      // +0.5 so a 1-pixel line lands on a pixel rather than across two.
      const yy = Math.round(yOf(db)) + 0.5;
      context.beginPath();
      context.moveTo(x, yy);
      context.lineTo(x + w, yy);
      context.stroke();
      context.textAlign = 'right';
      context.fillText(String(db), x - 6, yy);
    }

    // --- frequency: decades major, 2…9 minor (log) or ten ticks (linear) ----
    const { freqMinHz, freqMaxHz, freqScale } = currentOptions;
    const ticks: { hz: number; major: boolean }[] = [];
    if (freqScale === 'log') {
      const firstDecade = Math.floor(Math.log10(Math.max(freqMinHz, 1e-6)));
      const lastDecade = Math.ceil(Math.log10(freqMaxHz));
      for (let d = firstDecade; d <= lastDecade; d += 1) {
        const decade = 10 ** d;
        ticks.push({ hz: decade, major: true });
        for (const m of DECADE_MINORS) {
          ticks.push({ hz: decade * m, major: false });
        }
      }
    } else {
      const step = (freqMaxHz - freqMinHz) / 10;
      for (let i = 0; i <= 10; i += 1) {
        ticks.push({ hz: freqMinHz + i * step, major: i % 2 === 0 });
      }
    }
    context.textAlign = 'center';
    for (const tick of ticks) {
      if (tick.hz < freqMinHz || tick.hz > freqMaxHz) {
        continue;
      }
      const xx = Math.round(xOf(tick.hz)) + 0.5;
      context.strokeStyle = tick.major ? currentPalette.grid : currentPalette.gridMinor;
      context.beginPath();
      context.moveTo(xx, y);
      context.lineTo(xx, y + h);
      context.stroke();
      if (tick.major) {
        context.fillStyle = currentPalette.axisText;
        context.fillText(tick.hz >= 1000 ? `${String(tick.hz / 1000)}k` : String(Math.round(tick.hz)), xx, y + h + 11);
      }
    }

    // Unit labels: a dB axis with no unit is the "silently mixed" readout
    // ADR 0006 D3 forbids, and the unit is per FRAME (dBFS or dBFS/Hz), so it
    // is written by `paint` rather than here.
    context.restore();
  }

  /**
   * One polyline over the bins, reduced to at most one segment per pixel column.
   *
   * The MAXIMUM within a column, not the mean or the first bin: at N = 4096 and
   * an 8 kHz span there are several bins per pixel, and a mean would flatten
   * every narrow peak — the peak marker would then point at a level the trace
   * does not show. Taking the max is the same choice a spectrogram makes and it
   * is a DISPLAY reduction only; nothing downstream reads it.
   */
  function tracePath(frequencyHz: Float64Array, levelDb: Float64Array): void {
    const { x, w } = plot();
    const { freqMinHz, freqMaxHz } = currentOptions;
    context.beginPath();
    let started = false;
    let columnX = Number.NaN;
    let columnMax = Number.NEGATIVE_INFINITY;
    const flush = (): void => {
      if (!Number.isNaN(columnX)) {
        const yy = yOf(columnMax);
        if (started) {
          context.lineTo(columnX, yy);
        } else {
          context.moveTo(columnX, yy);
          started = true;
        }
      }
    };
    for (let k = 0; k < levelDb.length; k += 1) {
      const hz = frequencyHz[k] as number;
      if (hz < freqMinHz || hz > freqMaxHz) {
        continue;
      }
      const px = clamp(Math.round(xOf(hz)), x, x + w);
      if (px !== columnX) {
        flush();
        columnX = px;
        columnMax = Number.NEGATIVE_INFINITY;
      }
      const db = levelDb[k] as number;
      if (db > columnMax) {
        columnMax = db;
      }
    }
    flush();
  }

  function paint(frame: FrameMessage): void {
    const { x, y, w, h } = plot();
    context.save();

    // CLEAR THE WHOLE BACKING STORE, not the measured CSS box.
    //
    // `cssWidth`/`cssHeight` are what `resize()` last measured; the backing
    // store is what the browser actually allocated. When those disagree — a
    // paint that ran before the first ResizeObserver callback, a device-pixel
    // ratio change, an element laid out wider than the box we recorded —
    // filling only `cssWidth × cssHeight` leaves everything outside it holding
    // the PREVIOUS frame. It shows up as a ghost: the dBFS axis label drawn
    // twice, once where it belongs and once at the old right edge, which is
    // exactly what the light-theme screenshot caught on 2026-08-22.
    //
    // Resetting the transform is what makes the rectangle mean device pixels;
    // the scale is restored immediately after so every later call stays in CSS
    // pixels.
    context.setTransform(1, 0, 0, 1, 0, 0);
    context.fillStyle = currentPalette.background;
    context.fillRect(0, 0, canvas.width, canvas.height);
    context.scale(backingDpr, backingDpr);

    drawGrid();

    // --- hold first, so the live trace is never hidden by it -----------------
    if (frame.holdDb !== null) {
      context.save();
      context.strokeStyle = currentPalette.hold;
      context.lineWidth = 1;
      // Dashed as WELL as coloured: SC 1.4.1 again — the difference between
      // "now" and "loudest so far" must survive a monochrome screenshot.
      context.setLineDash([4, 3]);
      tracePath(frame.frequencyHz, frame.holdDb);
      context.stroke();
      context.restore();
    }

    // --- the trace, and its fill --------------------------------------------
    tracePath(frame.frequencyHz, frame.levelDb);
    context.save();
    context.lineJoin = 'round';
    context.strokeStyle = currentPalette.trace;
    context.lineWidth = 1.5;
    context.stroke();
    context.lineTo(x + w, y + h);
    context.lineTo(x, y + h);
    context.closePath();
    context.fillStyle = currentPalette.traceFill;
    context.fill();
    context.restore();

    // --- peak marker, labelled -----------------------------------------------
    const peakX = xOf(frame.peak.hz);
    const peakY = yOf(frame.peak.db);
    if (peakX >= x && peakX <= x + w) {
      context.save();
      context.strokeStyle = currentPalette.peakMarker;
      context.fillStyle = currentPalette.peakMarker;
      context.lineWidth = 1;
      context.beginPath();
      context.arc(peakX, peakY, 3.5, 0, 2 * Math.PI);
      context.stroke();
      context.font = '12px ui-monospace, "DejaVu Sans Mono", monospace';
      context.textBaseline = 'bottom';
      // The label carries BOTH numbers and BOTH units. A marker that only
      // changed colour would encode the reading in the colour (SC 1.4.1), and
      // a level with no unit could be read on the wrong axis (ADR 0006 D3).
      const label = `${frame.peak.hz.toFixed(1)} Hz  ${frame.peak.db.toFixed(1)} ${frame.levelUnit}`;
      const width = context.measureText(label).width;
      context.textAlign = peakX + width + 12 > x + w ? 'right' : 'left';
      context.fillText(label, context.textAlign === 'right' ? peakX - 8 : peakX + 8, peakY - 6);
      context.restore();
    }

    // --- clip -----------------------------------------------------------------
    if (frame.clipped) {
      context.save();
      context.fillStyle = currentPalette.clip;
      context.font = '600 13px ui-monospace, "DejaVu Sans Mono", monospace';
      context.textAlign = 'right';
      context.textBaseline = 'top';
      // The WORD, not a red border: ADR 0021 decision 1 lists the clipping flag
      // as a live overlay, and `live_singing`'s guidance is "clipping is
      // flagged, never tamed" — so it has to be readable, not inferable.
      context.fillText('CLIP', x + w, y);
      context.restore();
    }

    // --- the level unit, once, where the dB labels are -----------------------
    context.save();
    context.fillStyle = currentPalette.axisText;
    context.font = '11px ui-monospace, "DejaVu Sans Mono", monospace';
    context.textAlign = 'left';
    context.textBaseline = 'top';
    context.fillText(frame.levelUnit, 4, 2);
    context.restore();

    context.restore();
  }

  const scheduler: FrameScheduler<FrameMessage> = createFrameScheduler<FrameMessage>((frame) => {
    paint(frame);
  }, host);

  function resize(): void {
    const view = canvas.ownerDocument.defaultView;
    const dpr = view?.devicePixelRatio ?? 1;
    backingDpr = dpr;
    const measuredWidth = canvas.clientWidth;
    const measuredHeight = canvas.clientHeight;
    cssWidth = measuredWidth > 0 ? measuredWidth : cssWidth;
    cssHeight = measuredHeight > 0 ? measuredHeight : cssHeight;
    const backingWidth = Math.max(1, Math.round(cssWidth * dpr));
    const backingHeight = Math.max(1, Math.round(cssHeight * dpr));
    if (canvas.width !== backingWidth || canvas.height !== backingHeight) {
      canvas.width = backingWidth;
      canvas.height = backingHeight;
    }
    // Reset before scaling: setting width/height already clears the transform,
    // but `resize()` is also called on a dpr change alone, where it has not.
    context.setTransform(1, 0, 0, 1, 0, 0);
    context.scale(dpr, dpr);
    const last = scheduler.last;
    if (last !== null) {
      // Repaint immediately rather than waiting for the next frame: a resize
      // clears the backing store, and a paused or slow stream would leave the
      // panel blank for as long as it took the next hop to arrive.
      paint(last);
      return;
    }
    // No frame yet — but the canvas may not be empty. Stopping capture and
    // starting it again builds a NEW view over the SAME element, and whatever
    // the previous one painted is still there until the first hop arrives. Fill
    // it now, in this palette, so the gap reads as "not started" rather than as
    // a stale reading someone might believe.
    context.setTransform(1, 0, 0, 1, 0, 0);
    context.fillStyle = currentPalette.background;
    context.fillRect(0, 0, canvas.width, canvas.height);
    context.scale(dpr, dpr);
  }

  resize();

  return {
    draw(frame: FrameMessage): void {
      scheduler.submit(frame);
    },
    setOptions(next: SpectrumViewOptions): void {
      currentOptions = next;
      const last = scheduler.last;
      if (last !== null) {
        paint(last);
      }
    },
    setPalette(next: SpectrumPalette): void {
      currentPalette = next;
      const last = scheduler.last;
      if (last !== null) {
        paint(last);
      }
    },
    resize,
    get columnsDrawn(): number {
      return scheduler.drawn;
    },
    get columnsDropped(): number {
      return scheduler.dropped;
    },
    rafHz: () => scheduler.rafHz(),
    resetCounters: () => {
      scheduler.resetCounters();
    },
    destroy(): void {
      scheduler.cancel();
    },
  };
}
