//
// DROP, NEVER QUEUE — the rule extracted from the canvas so it can be tested.
//
// THE FAILURE THIS PREVENTS. Frames arrive from the Worker on the preset's hop
// (50 Hz at `live_singing`) and the display refreshes on `requestAnimationFrame`
// (60 Hz on a laptop, 60 or 120 on a phone, and 0 while the tab is hidden). The
// two rates are unrelated, and a renderer that drew every frame it was handed
// would build a queue the instant it fell behind: the trace would lag the voice
// by a growing amount, the singer would correct a pitch they stopped singing a
// second ago, and the READOUT WOULD STILL LOOK FINE — nothing about a stale
// frame looks stale. So a frame that arrives while one is already pending
// REPLACES it and the replaced one is COUNTED. `columnsDropped` is not a
// failure indicator; it is the difference between the frame rate and the
// display rate, and it is one of the numbers ADR 0021 decision 3 requires to be
// reported (its refresh is *measured, never claimed*).
//
// WHY IT IS ITS OWN MODULE. `requestAnimationFrame` does not exist in node, and
// a canvas is not testable there either. Splitting the RULE from the DRAWING
// puts the rule under `vitest --project unit` with a fake clock — which is the
// W1 contract's own instruction ("extract it into a pure `src/render/scheduler.ts`
// if that is what it takes to test it in node") — and leaves `spectrum-view.ts`
// with nothing but pixels.
// ----------------------------------------------------------------------------

/** The two functions this module needs from a display. Injectable, so node can supply a fake. */
export interface RafHost {
  request(callback: (timestampMs: number) => void): number;
  cancel(handle: number): void;
}

/** `window.requestAnimationFrame`, bound. The only place the browser global is named. */
export function browserRafHost(view: Window = window): RafHost {
  return {
    request: (callback) => view.requestAnimationFrame(callback),
    cancel: (handle) => {
      view.cancelAnimationFrame(handle);
    },
  };
}

/**
 * How many callback timestamps the rolling `rafHz` average is taken over.
 *
 * 30 at 60 Hz is half a second — long enough that one long frame does not
 * halve the reading, short enough that the number still responds when the tab
 * is throttled. `(prov.)`: chosen for legibility, not measured.
 */
export const RAF_WINDOW = 30;

export interface FrameScheduler<T> {
  /** Hand over the newest frame. Replaces any frame not yet drawn, and counts the replacement. */
  submit(frame: T): void;
  /** Cancel a pending callback and forget the pending frame. Idempotent. */
  cancel(): void;
  /** Is a callback outstanding? */
  readonly pending: boolean;
  readonly drawn: number;
  readonly dropped: number;
  /** The most recently drawn frame, or `null`. Used by `resize()` to repaint without waiting. */
  readonly last: T | null;
  /** Callbacks per second over the last `RAF_WINDOW` of them; `0` until two have arrived. */
  rafHz(): number;
  /** Zero `drawn`, `dropped` and the rate window. Does NOT cancel a pending callback. */
  resetCounters(): void;
}

/**
 * A scheduler that draws at most one frame per animation callback, always the
 * newest one submitted.
 *
 * `draw` is called from inside the host's callback, so it sees the same
 * timestamp the browser passed — the number a refresh measurement is made of.
 */
export function createFrameScheduler<T>(
  draw: (frame: T, timestampMs: number) => void,
  host: RafHost,
): FrameScheduler<T> {
  let next: T | null = null;
  let handle: number | null = null;
  let last: T | null = null;
  let drawn = 0;
  let dropped = 0;
  let stamps: number[] = [];

  function onFrame(timestampMs: number): void {
    handle = null;
    const frame = next;
    next = null;
    stamps.push(timestampMs);
    if (stamps.length > RAF_WINDOW) {
      stamps = stamps.slice(stamps.length - RAF_WINDOW);
    }
    if (frame === null) {
      // Cancelled between the request and the callback. Nothing to draw, and
      // NOT counted as a drop: no frame was superseded.
      return;
    }
    last = frame;
    drawn += 1;
    draw(frame, timestampMs);
  }

  return {
    submit(frame: T): void {
      if (next !== null) {
        // A frame was already waiting for the next callback and will never be
        // seen. THIS is the drop, and it is counted here rather than in the
        // callback so that a frame dropped by `cancel()` is not miscounted as
        // one the display could not keep up with.
        dropped += 1;
      }
      next = frame;
      if (handle === null) {
        handle = host.request(onFrame);
      }
    },

    cancel(): void {
      if (handle !== null) {
        host.cancel(handle);
        handle = null;
      }
      next = null;
    },

    get pending(): boolean {
      return handle !== null;
    },

    get drawn(): number {
      return drawn;
    },

    get dropped(): number {
      return dropped;
    },

    get last(): T | null {
      return last;
    },

    rafHz(): number {
      if (stamps.length < 2) {
        return 0;
      }
      const first = stamps[0] as number;
      const final = stamps[stamps.length - 1] as number;
      const span = final - first;
      // A zero span means a fake clock or a stall reported at one instant;
      // returning 0 is the honest answer, not Infinity.
      return span > 0 ? ((stamps.length - 1) * 1000) / span : 0;
    },

    resetCounters(): void {
      drawn = 0;
      dropped = 0;
      stamps = [];
    },
  };
}
