//
// The DC blocker — ADR 0006 D7's one-pole–one-zero form, in TypeScript.
//
//     y[n] = x[n] − x[n−1] + R·y[n−1],     R = 1 − 2π·f_c/f_s
//
// One state pair, applied BEFORE the window and AFTER the 1/32768 scaling
// (ADR 0003 d.2). `R` is recorded per take. The RBJ biquad is the recorded
// rejected alternative: not on conditioning (that argument is real but not
// decisive) but because a biquad is a second implementation to keep in step
// with the host for no measured gain.
//
// STATEFUL ACROSS CHUNKS, ON PURPOSE. The live path calls this once per hop,
// on a slice of a continuous stream; a filter that reset between hops would
// inject a step at every hop boundary and put a broadband click into every
// frame — a defect that looks exactly like a microphone problem. `reset()` is
// therefore explicit and is called when the STREAM changes, never per frame.
//
// THE TWO NUMBERS ADR 0006 D7 STATES, which `tests/unit/dcblock-response.test.ts`
// verifies from the transfer function rather than trusting:
//   * −3.0018 dB at f_c (against −3.0103 dB for an ideal analog single pole);
//   * a high-frequency asymptote of |H(−1)| = 2/(1+R) = +0.0171 dB.
// The row exists so that the watch and the host compute the SAME filter, not
// because the form is inaccurate: its own shelf error is ≈ +0.017 dB, and a
// tolerance row written at the ≈ 0.3 dB this record once claimed would have
// accepted, invisibly, a defect two orders of magnitude larger.
// ----------------------------------------------------------------------------

/** `R = 1 − 2π·f_c/f_s` (ADR 0006 D7). 0.996073 at 20 Hz / 32 kHz — the value every preset asks for. */
export function dcBlockerPole(cutoffHz: number, sampleRateHz: number): number {
  if (!(cutoffHz > 0) || !(sampleRateHz > 0)) {
    throw new RangeError('cutoff and sample rate must be positive');
  }
  const r = 1 - (2 * Math.PI * cutoffHz) / sampleRateHz;
  if (!(r > 0) || r >= 1) {
    throw new RangeError(
      `R = ${String(r)} is outside (0, 1): f_c = ${String(cutoffHz)} Hz is not a corner at f_s = ` +
        `${String(sampleRateHz)} Hz (the one-pole form needs 2π·f_c ≪ f_s)`,
    );
  }
  return r;
}

/**
 * `20·log10 |H(e^{jω})|` of `H(z) = (1 − z⁻¹)/(1 − R·z⁻¹)` at `fHz`.
 *
 *     |H| = |1 − e^{−jω}| / |1 − R·e^{−jω}|,   ω = 2π f / f_s
 *
 * Written from the transfer function, in one place, so that the test and any
 * capture-chain readout quote the same expression the filter implements.
 */
export function dcBlockerResponseDb(fHz: number, cutoffHz: number, sampleRateHz: number): number {
  const r = dcBlockerPole(cutoffHz, sampleRateHz);
  const w = (2 * Math.PI * fHz) / sampleRateHz;
  const cw = Math.cos(w);
  const numeratorSq = 2 - 2 * cw; // |1 − e^{−jω}|²
  const denominatorSq = 1 - 2 * r * cw + r * r; // |1 − R·e^{−jω}|²
  return 10 * Math.log10(numeratorSq / denominatorSq);
}

/** A first-order DC blocker holding its own `x[n−1]` and `y[n−1]` across chunks. */
export class DcBlocker {
  readonly cutoffHz: number;
  readonly sampleRateHz: number;

  /** The pole radius `R`; recorded per take (ADR 0006 D7). */
  readonly r: number;

  private x1 = 0;
  private y1 = 0;

  constructor(cutoffHz: number, sampleRateHz: number) {
    this.cutoffHz = cutoffHz;
    this.sampleRateHz = sampleRateHz;
    this.r = dcBlockerPole(cutoffHz, sampleRateHz);
  }

  /** Clear `x[n−1]` and `y[n−1]`. Call on a STREAM change (new capture, new file), never per frame. */
  reset(): void {
    this.x1 = 0;
    this.y1 = 0;
  }

  /** `20·log10 |H|` at `fHz` for this instance's `R`. */
  responseDb(fHz: number): number {
    return dcBlockerResponseDb(fHz, this.cutoffHz, this.sampleRateHz);
  }

  /**
   * Filter one chunk in stream order, advancing the state.
   *
   * `out` may alias `input` (the live path filters in place). When `out` is
   * omitted a fresh Float64Array is allocated — convenient for tests, wrong for
   * a 50 Hz loop, which passes its own buffer.
   */
  process(input: Float64Array | Float32Array, out?: Float64Array): Float64Array {
    const y = out ?? new Float64Array(input.length);
    if (y.length < input.length) {
      throw new RangeError(`out needs ${String(input.length)} slots, got ${String(y.length)}`);
    }
    let { x1, y1 } = this;
    const { r } = this;
    for (let i = 0; i < input.length; i += 1) {
      const x = input[i] as number;
      const v = x - x1 + r * y1;
      y[i] = v;
      x1 = x;
      y1 = v;
    }
    this.x1 = x1;
    this.y1 = y1;
    return y;
  }
}
