//
// Open the microphone, assert the rate, load the worklet. The only file in the
// application that names `getUserMedia` or constructs an `AudioContext`.
//
// EVERY DECISION IN HERE WAS MOVED OUT. What remains is sequence and cleanup:
// the refusal is `chain.rateVerdict`, the resampler sentence is
// `chain.describeResampler`, the snapshot is `chain.buildChain`, and all three
// are unit-tested in node. This file is the part that can only be tested by a
// person with a microphone in front of a browser, so it is kept as small as
// that fact deserves (roadmap W1: "Alexander runs the two browsers").
//
// THE ORDER MATTERS AND IS NOT ARBITRARY.
//   1. `getUserMedia` FIRST. Until permission is granted, `getSettings().label`
//      is empty and `enumerateDevices` gives unlabelled entries, so a chain
//      snapshot taken earlier could not name the device it describes.
//   2. `new AudioContext({sampleRate})` SECOND, and its rate read back. The
//      constructor argument is a request; Firefox honours it, Chromium honours
//      it on most devices, and neither promises to. ADR 0021 decision 7(c):
//      a mismatch REFUSES to start and names both numbers.
//   3. `addModule` THIRD, and only after the rate is accepted — loading a
//      module into a context that is about to be closed is work nobody needs.
//
// ON `stop()` AND WHY BOTH HALVES ARE CLOSED. A `MediaStreamTrack` left running
// keeps the browser's recording indicator lit and, on a phone, keeps the
// microphone route open — which is a battery cost and, more to the point, a
// singer who cannot tell whether the page is listening. An `AudioContext` left
// open keeps a real-time audio thread alive. `close()` here does both, in that
// order, and is idempotent.
// ----------------------------------------------------------------------------

// The worklet asset. THE IMPORT FORM IS LOAD-BEARING, and it is not the one the
// W1 contract guessed: measured against Vite 7.3.6 on 2026-08-22,
// `new URL('./pcm-hop.worklet.ts?worker&url', import.meta.url)` emits NO asset —
// it inlines the raw, untranspiled TypeScript as a `data:video/mp2t` URL, which
// `addModule()` would then fail to parse. The `import … from '…?worker&url'`
// form below emits `dist/assets/pcm-hop.worklet-<hash>.js` (an ES module, because
// `vite.config.ts` sets `worker.format: 'es'`, which is what `addModule`
// requires) and references it from the bundle by that name. Verified by a grep
// of `dist/` in the same run that built it.
import pcmHopWorkletUrl from './pcm-hop.worklet.ts?worker&url';

import {
  CAPTURE_CHANNEL_COUNT,
  buildChain,
  rateVerdict,
  requestedConstraints,
  type CaptureChain,
  type RateVerdict,
  type TrackFacts,
} from './chain';

/** The processor name registered by `pcm-hop.worklet.ts`. Changing it changes both files. */
export const PCM_HOP_PROCESSOR = 'spectral-pcm-hop';

/**
 * The rate refusal of ADR 0021 decision 7(c), as a typed error.
 *
 * Typed rather than a bare `Error` so the shell can render `verdict.reason` as
 * the banner it is meant to be — "never a thrown TypeError in a console nobody
 * has open".
 */
export class RateRefused extends Error {
  readonly verdict: RateVerdict;
  constructor(verdict: RateVerdict) {
    super(verdict.reason);
    this.name = 'RateRefused';
    this.verdict = verdict;
  }
}

/** Raised when the origin cannot capture at all — the insecure-origin case, as an error. */
export class CaptureUnavailable extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'CaptureUnavailable';
  }
}

export interface CaptureOptions {
  /** The preset's `analysis.sample_rate_hz`. Asserted, never resampled. */
  readonly sampleRateHz: number;
  /** The preset's `analysis.fft_size` — the worklet's ring length. */
  readonly windowLength: number;
  /** The preset's `analysis.resolution.hop_samples`. */
  readonly hopSamples: number;
  /** ADR 0006 D7's corner and its pole radius, for the chain readout. `null` when the blocker is off. */
  readonly dcBlocker: { readonly cutoffHz: number; readonly R: number } | null;
  /** A specific input device, when the caller has one. W1 always takes the default. */
  readonly deviceId?: string;
}

export interface OpenCapture {
  readonly chain: CaptureChain;
  readonly context: AudioContext;
  /** The worklet node. Its `port` delivers one message per hop. */
  readonly node: AudioWorkletNode;
  readonly stream: MediaStream;
  close(): Promise<void>;
}

/** A `getSettings()` dictionary, copied field by field into a plain snapshot. */
function trackFacts(track: MediaStreamTrack): TrackFacts {
  const settings = track.getSettings();
  // Spread conditionally, never `key: value ?? undefined`: `tsconfig` sets
  // `exactOptionalPropertyTypes`, under which an explicit `undefined` is a
  // PRESENT key with an undefined value — which would turn "the browser did not
  // report auto-gain" into "the key exists", and `processingVerdict` reads the
  // difference.
  //
  // `typeof x === 'boolean'`, not `x !== undefined`: the DOM lib types
  // `echoCancellation` as `string | boolean` (the spec allows the
  // "echoCancellationType" style string on some engines), and `processingVerdict`
  // asks a three-state question — true, false, or "the browser did not say". A
  // string coerced to a boolean would answer it wrongly and confidently.
  //
  // `latency` is read through a widened view because it is not in this
  // TypeScript's `MediaTrackSettings` yet, though Chromium reports it. An
  // absent key is the honest result on an engine that does not.
  const extra = settings as Readonly<Record<string, unknown>>;
  return {
    ...(settings.deviceId !== undefined ? { deviceId: settings.deviceId } : {}),
    ...(track.label !== '' ? { label: track.label } : {}),
    ...(settings.sampleRate !== undefined ? { sampleRate: settings.sampleRate } : {}),
    ...(settings.channelCount !== undefined ? { channelCount: settings.channelCount } : {}),
    ...(typeof settings.echoCancellation === 'boolean' ? { echoCancellation: settings.echoCancellation } : {}),
    ...(typeof settings.noiseSuppression === 'boolean' ? { noiseSuppression: settings.noiseSuppression } : {}),
    ...(typeof settings.autoGainControl === 'boolean' ? { autoGainControl: settings.autoGainControl } : {}),
    ...(typeof extra['latency'] === 'number' ? { latency: extra['latency'] } : {}),
  };
}

/** `getCapabilities()` where it exists (Chromium), `{}` where it does not (Firefox until recently). */
function capabilitiesOf(track: MediaStreamTrack): Readonly<Record<string, unknown>> {
  const getCapabilities = (track as { getCapabilities?: () => MediaTrackCapabilities }).getCapabilities;
  if (typeof getCapabilities !== 'function') {
    return {};
  }
  try {
    return { ...getCapabilities.call(track) } as Record<string, unknown>;
  } catch {
    // A browser that has the method and throws is telling us it does not
    // support the track type. Not a capture failure; an absent readout.
    return {};
  }
}

/**
 * Open the microphone and bring up the capture graph.
 *
 * Throws `CaptureUnavailable` on an origin without `mediaDevices`,
 * `RateRefused` on decision 7(c)'s mismatch, and whatever `getUserMedia` throws
 * on a denied permission (`NotAllowedError`) — unwrapped, because the browser's
 * own name for that failure is the one a search engine answers.
 */
export async function openCapture(options: CaptureOptions): Promise<OpenCapture> {
  const media = navigator.mediaDevices as MediaDevices | undefined;
  if (media === undefined) {
    throw new CaptureUnavailable(
      'navigator.mediaDevices is not available on this origin. It exists only in a secure context ' +
        '(HTTPS, or localhost): serve the app over HTTPS with an mkcert certificate for phone-on-LAN ' +
        '(ADR 0021 decision 8).',
    );
  }

  const requested = requestedConstraints(options.sampleRateHz);
  const stream = await media.getUserMedia({
    audio: {
      channelCount: CAPTURE_CHANNEL_COUNT,
      // The three that matter. ADR 0021 decision 8: mandatory AND insufficient
      // — they are a request, and the read-back below is what says whether the
      // request was honoured.
      echoCancellation: false,
      noiseSuppression: false,
      autoGainControl: false,
      sampleRate: options.sampleRateHz,
      ...(options.deviceId !== undefined ? { deviceId: { exact: options.deviceId } } : {}),
    },
    video: false,
  });

  const track = stream.getAudioTracks()[0];
  if (track === undefined) {
    stream.getTracks().forEach((t) => {
      t.stop();
    });
    throw new CaptureUnavailable('getUserMedia returned a stream with no audio track');
  }

  const context = new AudioContext({ sampleRate: options.sampleRateHz });
  const facts = trackFacts(track);
  const verdict = rateVerdict(options.sampleRateHz, context.sampleRate, facts.sampleRate ?? null);
  if (!verdict.ok) {
    await context.close();
    stream.getTracks().forEach((t) => {
      t.stop();
    });
    throw new RateRefused(verdict);
  }

  await context.audioWorklet.addModule(pcmHopWorkletUrl);
  const source = context.createMediaStreamSource(stream);
  const node = new AudioWorkletNode(context, PCM_HOP_PROCESSOR, {
    numberOfInputs: 1,
    // ZERO OUTPUTS. This node is a sink: it analyses and posts, it never
    // returns audio. A node with an output would have to be connected to
    // `destination` to be pulled, which would feed the microphone back to the
    // speakers — a howl in a rehearsal room, and an echo path in a measurement.
    numberOfOutputs: 0,
    channelCount: CAPTURE_CHANNEL_COUNT,
    channelCountMode: 'explicit',
    channelInterpretation: 'discrete',
    processorOptions: { windowLength: options.windowLength, hopSamples: options.hopSamples },
  });
  source.connect(node);

  // Autoplay policy: a context created outside a user gesture starts
  // `suspended`. `startSession` is called from the button handler, so this
  // resolves immediately — but calling it unconditionally is what makes the
  // debug surface's `start()` work from a harness too.
  if (context.state === 'suspended') {
    await context.resume();
  }

  const chain = buildChain({
    presetSampleRate: options.sampleRateHz,
    contextSampleRate: context.sampleRate,
    requested,
    track: facts,
    capabilities: capabilitiesOf(track),
    baseLatencyS: context.baseLatency,
    outputLatencyS: typeof context.outputLatency === 'number' ? context.outputLatency : null,
    dcBlocker: options.dcBlocker,
    userAgent: navigator.userAgent,
  });

  let closed = false;
  return {
    chain,
    context,
    node,
    stream,
    async close(): Promise<void> {
      if (closed) {
        return;
      }
      closed = true;
      node.port.onmessage = null;
      source.disconnect();
      node.disconnect();
      stream.getTracks().forEach((t) => {
        t.stop();
      });
      await context.close();
    },
  };
}
